-- ============================================================
--  Тема «Майбутні часи (Future Forms)»: теорія у кроковому форматі + вправи
--  Згенеровано з mig/future_tenses.js — вручну не редагувати.
--  Потребує 06_theory_structure.sql. Повторний запуск безпечний.
-- ============================================================
begin;

alter table public.topics        add column if not exists subtopics jsonb not null default '[]'::jsonb;
alter table public.theory_blocks add column if not exists subtopic  text;
alter table public.exercises     add column if not exists subtopic  text;

create unique index if not exists uq_exercises_legacy_shared
  on public.exercises (legacy_id) where student_id is null;
-- тип вправи «translate» (переклад і письмо) дозволено в exercises.type
alter table public.exercises drop constraint if exists exercises_type_check;
alter table public.exercises add constraint exercises_type_check
  check (type in ('order', 'choice', 'gap', 'cross', 'abcd', 'translate'));
alter table public.theory_blocks drop constraint if exists theory_blocks_kind_check;
alter table public.theory_blocks add constraint theory_blocks_kind_check
  check (kind in ('prose', 'hero', 'cases', 'formula', 'traps', 'pairs'));

insert into public.topics (slug, title, description, position, subtopics)
values ($g0$future_tenses$g0$, $g1$Майбутні часи (Future Forms)$g1$, $g2$Future Simple, be going to, Present Continuous / Simple для майбутнього, Future Continuous, Future Perfect і Future Perfect Continuous: форми, вживання, слова-маркери, типові помилки, порівняння. Є вправи на переклад речень з перевіркою й поясненням помилок.$g2$, 15, $g3$[{"slug":"fut_simple","title":"Future Simple, be going to та Present для майбутнього","description":"Як сказати про майбутнє: will, be going to, Present Continuous і Present Simple. Коли який варіант і чим вони різняться."},{"slug":"fut_cont","title":"Future Continuous: дія в процесі в майбутньому","description":"Дія триватиме в певний момент або період у майбутньому; ввічливе запитання про плани."},{"slug":"fut_perf","title":"Future Perfect: завершиться до моменту в майбутньому","description":"Дія буде завершена до певного моменту в майбутньому. By, by the time, before."},{"slug":"fut_perf_cont","title":"Future Perfect Continuous: тривалість до моменту в майбутньому","description":"Дія триватиме певний час до моменту в майбутньому. For, by, how long."},{"slug":"fut_mix","title":"Усі майбутні часи разом","description":"Порівняння майбутніх часів, вибір потрібного, змішані вправи й тести. Окремої теорії тут мало: усе — у попередніх підтемах.","mix":true}]$g3$::jsonb)
on conflict (slug) do update set title = excluded.title,
  description = excluded.description, position = excluded.position, subtopics = excluded.subtopics;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g4$fs_form$g4$, $g5$Future Simple: як утворюється$g5$, $g6$elementary$g6$, $g7$formula$g7$, $g8${"step":"Future Simple: як утворюється","kicker":"Як утворюється","lead":"Future Simple = <b>will</b> + дієслово без to. Will однакове для всіх осіб. У британській граматиці з <b>I</b> і <b>we</b> у пропозиціях і запитаннях-порадах ще вживають <b>shall</b>.","tiles":[{"role":"підмет","label":"I / he / they…","tone":"noun"},{"role":"will","label":"will","tone":"colour"},{"role":"V","label":"call","tone":"origin"}],"legend":[{"tone":"noun","label":"для всіх осіб — will"},{"tone":"origin","label":"дієслово в початковій формі, без to й без -s"}],"examples":[{"text":"I <b>will call</b> you tomorrow.","plain":"I will call you tomorrow.","note":"ствердження"},{"text":"She <b>won't come</b> to the party.","plain":"She won't come to the party.","note":"заперечення"},{"text":"<b>Will</b> you <b>help</b> me?","plain":"Will you help me?","note":"питання"},{"text":"<b>Shall</b> I <b>open</b> the window?","plain":"Shall I open the window?","note":"пропозиція"}],"note":"Скорочення: <i>I'll, he'll, they'll, won't</i>. <b>Shall I…? Shall we…?</b> — пропозиція чи порада: <i>Shall we go for a walk?</i> Не <i>Will we go?</i>","tabs":[{"title":"Усі форми","html":"<div class=\"overflow-x-auto mb-3\"><table class=\"w-full text-body-sm border-collapse\">\n  <thead><tr><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\"></th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Ствердження</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Заперечення</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Питання</th></tr></thead>\n  <tbody><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">I / you / he / she / it / we / they</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">will call</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">won't (will not) call</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">Will he call?</td></tr></tbody>\n</table></div>"}]}$g8$::jsonb, null, 0, $g9$fut_simple$g9$
from public.topics where slug = $g10$future_tenses$g10$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position, subtopic = excluded.subtopic;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g11$fs_will$g11$, $g12$Future Simple: коли вживаємо will$g12$, $g13$elementary$g13$, $g14$cases$g14$, $g15${"kicker":"Коли вживаємо","lead":"Will — це «щось станеться», але без чіткого плану чи підготовки. Ми або прогнозуємо, або вирішуємо просто зараз.","cards":[{"icon":"⚡","title":"Рішення в момент мовлення","text":"Тільки-но вирішили, нічого не планували заздалегідь.","example":"I'm tired. I <b>will go</b> to bed earlier today.","examplePlain":"I'm tired. I will go to bed earlier today."},{"icon":"?","title":"Прогноз, припущення, побоювання","text":"Після I think, I hope, I'm sure, I'm afraid, probably, perhaps. Ми не впевнені.","example":"I'm sure he <b>will help</b> you. He <b>will probably</b> come home late.","examplePlain":"I'm sure he will help you. He will probably come home late."},{"icon":"∞","title":"Факти про майбутнє","text":"На них ми не впливаємо: календар, вік, природа.","example":"It <b>will be</b> Monday tomorrow. The sun <b>will rise</b> at six.","examplePlain":"It will be Monday tomorrow. The sun will rise at six."},{"icon":"🤝","title":"Обіцянка, погроза, пропозиція","text":"Promise, threaten, offer.","example":"I promise I <b>will buy</b> you new trainers. <b>Shall</b> I help you?","examplePlain":"I promise I will buy you new trainers. Shall I help you?"}]}$g15$::jsonb, null, 1, $g16$fut_simple$g16$
from public.topics where slug = $g17$future_tenses$g17$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position, subtopic = excluded.subtopic;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g18$fs_gt$g18$, $g19$Be going to: коли вживаємо$g19$, $g20$elementary$g20$, $g21$cases$g21$, $g22${"kicker":"Коли вживаємо","lead":"Be going to = <b>am / is / are going to</b> + дієслово. Це майбутнє, яке вже «розігнане»: є план або є ознаки, що воно скоро буде.","cards":[{"icon":"📝","title":"Наміри й плани","text":"Ми вже вирішили, що робитимемо.","example":"He <b>is going to enter</b> a computer college. (he has already decided)","examplePlain":"He is going to enter a computer college. (he has already decided)"},{"icon":"👁","title":"Близька подія з ознаками","text":"Ми бачимо підстави: хмари, чужа швидкість, готові приготування.","example":"Look at those clouds! It <b>is going to rain</b>.","examplePlain":"Look at those clouds! It is going to rain."},{"icon":"⚠","title":"Щойно зрозуміли, що зараз станеться","text":"Попередження перед подією.","example":"Be careful! You <b>are going to cut</b> your finger!","examplePlain":"Be careful! You are going to cut your finger!"}],"axis":{"title":"Will і be going to на осі","points":[{"label":"зараз","text":"will: вирішили просто тепер"},{"label":"раніше","text":"be going to: уже вирішили або бачимо ознаки"},{"label":"потім","text":"подія в майбутньому"}],"note":"Одну й ту саму подію можна назвати обома способами; різниця в тому, коли ми про неї подумали."}}$g22$::jsonb, null, 2, $g23$fut_simple$g23$
