insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g25$fs_vs$g25$, $g26$Will чи be going to?$g26$, $g27$elementary$g27$, $g28$pairs$g28$, $g29${"step":"Will чи be going to?","kicker":"Порівняння","lead":"Перевірте два запитання: <b>чи є вже план чи ознаки?</b> та <b>чи вирішили ми це щойно?</b>","groups":[{"title":"Will","note":"ще без плану","items":[["рішення просто зараз","It's too cold. I'll turn on the heating."],["прогноз з I think / I'm sure","I think he'll win."],["факт, на який не впливаємо","She will be five next year."],["обіцянка, пропозиція","I'll help you. Shall I open the door?"]]},{"title":"Be going to","note":"план або ознаки","items":[["уже ухвалений намір","I'm going to buy a new camera. I've saved some money."],["підготовка вже йде","They've bought a lot of food. They are going to have a party."],["очевидна ознака","The dog is going to bite you!"],["щойно зрозуміли","Watch out! You are going to hit your head!"]]}],"notes":["<b>Тест:</b> «Ми вже вирішили?» — be going to. «Вирішуємо тільки зараз / здогадуємось?» — will."]}$g29$::jsonb, null, 3, $g30$fut_simple$g30$
