insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g32$fs_present$g32$, $g33$Present Continuous і Present Simple для майбутнього$g33$, $g34$elementary$g34$, $g35$cases$g35$, $g36${"kicker":"Коли вживаємо","lead":"Про майбутнє можна говорити й теперішніми часами. Вони звучать упевненіше, бо йдеться про домовленість чи розклад.","cards":[{"icon":"📅","title":"Present Continuous: домовлений план","text":"Подія обов'язково відбудеться найближчим часом: є час, місце, квитки.","example":"We <b>are having</b> an exam in a week. She <b>is flying</b> to Rome next Tuesday.","examplePlain":"We are having an exam in a week. She is flying to Rome next Tuesday."},{"icon":"➡","title":"Go і come у Present Continuous","text":"Щоб не повторювати «going to go», кажемо просто is going / is coming.","example":"They <b>are going</b> to the gym tonight. Our aunt <b>is coming</b> tomorrow.","examplePlain":"They are going to the gym tonight. Our aunt is coming tomorrow."},{"icon":"⏱","title":"Present Simple: розклад","text":"Потяги, сеанси, уроки, години роботи.","example":"The train <b>arrives</b> at eight o'clock tomorrow morning.","examplePlain":"The train arrives at eight o'clock tomorrow morning."}]}$g36$::jsonb, null, 4, $g37$fut_simple$g37$
