insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g39$fs_markers$g39$, $g40$Слова-маркери та конструкції$g40$, $g41$elementary$g41$, $g42$pairs$g42$, $g43${"step":"Слова-маркери та конструкції","kicker":"Слова-маркери","lead":"Слова перед майбутнім часто підказують, який варіант потрібен.","groups":[{"title":"Зазвичай will","note":"прогноз, думка","items":[["I think / I believe / I expect","I think I'll buy a new camera."],["I hope / I'm afraid / I'm sure","I'm afraid we'll miss the train."],["probably / perhaps","He will probably come home late."],["I promise / I know","I promise I won't tell anyone."]]},{"title":"Маркери майбутнього часу","note":"стоять у кінці або на початку","items":[["tomorrow","I'll call you tomorrow."],["next week / month / year","We are flying next week."],["in a month / in three days","It will be Christmas in three days."],["soon / tonight / in 2100","People will live on other planets in 2100."]]}],"notes":["<b>Запитання «Що робити?»:</b> <i>Shall I print this document? Shall we go?</i> — з I і we. До співрозмовника: <i>Will you help me? Will you join us?</i>"]}$g43$::jsonb, null, 5, $g44$fut_simple$g44$
