insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g46$fs_traps$g46$, $g47$Майбутнє: типові помилки$g47$, $g48$intermediate$g48$, $g49$traps$g49$, $g50${"kicker":"Типові помилки","lead":"Найчастіше плутають will і be going to, а також вживають Future Simple там, де потрібен розклад або домовленість.","items":[{"title":"Will для вже ухваленого плану","bad":"I have bought the tickets. I will fly to Rome.","good":"I have bought the tickets. I <b>am going to fly</b> to Rome.","goodPlain":"I have bought the tickets. I am going to fly to Rome.","rule":"Є план і квитки: be going to (або I'm flying)."},{"title":"Be going to для миттєвого рішення","bad":"I feel cold. I am going to close the window.","good":"I feel cold. I <b>will close</b> the window.","goodPlain":"I feel cold. I will close the window.","rule":"Рішення прямо зараз: will."},{"title":"Will після when / if / as soon as","bad":"When I will arrive, I'll call you.","good":"When I <b>arrive</b>, I'll call you.","goodPlain":"When I arrive, I'll call you.","rule":"Після when, if, before, after, as soon as — Present Simple (про це — в умовних реченнях)."},{"title":"Shall з he / they","bad":"Shall he come? They shall help us.","good":"<b>Will</b> he come? They <b>will</b> help us.","goodPlain":"Will he come? They will help us.","rule":"Shall — лише з I і we."},{"title":"Future Simple для розкладу","bad":"The train will leave at 8.","good":"The train <b>leaves</b> at 8.","goodPlain":"The train leaves at 8.","rule":"Розклад, програма — Present Simple."}]}$g50$::jsonb, null, 6, $g51$fut_simple$g51$
