insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g53$fc_form$g53$, $g54$Future Continuous: як утворюється$g54$, $g55$elementary$g55$, $g56$formula$g56$, $g57${"step":"Future Continuous: як утворюється","kicker":"Як утворюється","lead":"Future Continuous = <b>will be</b> + дієслово з <b>-ing</b>. Will be однакове для всіх осіб.","tiles":[{"role":"підмет","label":"I / he / they…","tone":"noun"},{"role":"will be","label":"will be","tone":"colour"},{"role":"V-ing","label":"playing","tone":"origin"}],"legend":[{"tone":"noun","label":"для всіх осіб — will be"},{"tone":"origin","label":"правопис -ing такий самий, як у Present Continuous"}],"examples":[{"text":"I <b>will be playing</b> football at 4 o'clock tomorrow.","plain":"I will be playing football at 4 o'clock tomorrow.","note":"ствердження"},{"text":"They <b>won't be working</b> at 7 o'clock.","plain":"They won't be working at 7 o'clock.","note":"заперечення"},{"text":"<b>Will</b> you <b>be using</b> the car tonight?","plain":"Will you be using the car tonight?","note":"питання"},{"text":"What <b>will</b> she <b>be doing</b> at 8?","plain":"What will she be doing at 8?","note":"спеціальне питання"}],"note":"Скорочення: <i>I'll be working, won't be working</i>. У питанні will виходить перед підметом: <i>Will they be swimming?</i>","tabs":[{"title":"Усі форми","html":"<div class=\"overflow-x-auto mb-3\"><table class=\"w-full text-body-sm border-collapse\">\n  <thead><tr><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\"></th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Ствердження</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Заперечення</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Питання</th></tr></thead>\n  <tbody><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">I / you / he / she / it / we / they</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">will be playing</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">won't be playing</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">Will he be playing?</td></tr></tbody>\n</table></div>"}]}$g57$::jsonb, null, 7, $g58$fut_cont$g58$
