insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g60$fc_use$g60$, $g61$Future Continuous: коли вживаємо$g61$, $g62$elementary$g62$, $g63$cases$g63$, $g64${"kicker":"Коли вживаємо","lead":"Future Continuous малює «картинку» майбутнього: що саме тоді буде відбуватись.","cards":[{"icon":"●","title":"Дія в певний момент у майбутньому","text":"Час названо: at 5 o'clock tomorrow, this time next week.","example":"This time next week we <b>will be skiing</b> in the mountains.","examplePlain":"This time next week we will be skiing in the mountains."},{"icon":"⌛","title":"Дія протягом періоду","text":"Від і до чи весь день.","example":"They <b>will be playing</b> chess from 5 to 7.","examplePlain":"They will be playing chess from 5 to 7."},{"icon":"📌","title":"Неминуча чи заздалегідь домовлена дія","text":"Наче «так у нас заплановано, це станеться само».","example":"I'll be speaking to John tomorrow. (we will definitely meet)","examplePlain":"I'll be speaking to John tomorrow. (we will definitely meet)"},{"icon":"🙂","title":"Ввічливе запитання про плани","text":"Щоб про щось попросити чи запропонувати. Звучить м'якше, ніж Will you…?","example":"<b>Will you be going</b> shopping? Can you buy a loaf of bread for me?","examplePlain":"Will you be going shopping? Can you buy a loaf of bread for me?"}],"axis":{"title":"Future Continuous на осі","points":[{"label":"тепер","text":"говоримо"},{"label":"момент X","text":"дія вже йде"},{"label":"після","text":"продовжується"}],"note":"Нас цікавить саме тоді: що в цей момент відбуватиметься."}}$g64$::jsonb, null, 8, $g65$fut_cont$g65$
