insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g67$fc_markers$g67$, $g68$Future Continuous: слова-маркери$g68$, $g69$elementary$g69$, $g70$pairs$g70$, $g71${"step":"Future Continuous: слова-маркери","kicker":"Слова-маркери","lead":"Маркери називають конкретний момент або період, у який дія триватиме.","groups":[{"title":"Момент або період","note":"що саме буде відбуватись","items":[["at 5 o'clock tomorrow","I will be working at 5 o'clock tomorrow."],["at this time tomorrow / next week","At this time tomorrow we will be flying."],["from 9 to 12","He will be sleeping from 9 to 12."],["all day / all the evening","She will be studying all day."],["next Friday at ten","They will be competing next Friday at ten."]]}],"notes":["<b>Дієслова стану</b> (know, like, want) не вживаються в Continuous: <i>I will know the results tomorrow.</i>"]}$g71$::jsonb, null, 9, $g72$fut_cont$g72$
