insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g74$fc_traps$g74$, $g75$Future Continuous: типові помилки$g75$, $g76$intermediate$g76$, $g77$traps$g77$, $g78${"kicker":"Типові помилки","lead":"Тут помиляються на структурі (will be + V-ing) та на виборі між Future Simple і Future Continuous.","items":[{"title":"Забули be","bad":"I will watching TV at 6.","good":"I <b>will be watching</b> TV at 6.","goodPlain":"I will be watching TV at 6.","rule":"Future Continuous = will be + -ing."},{"title":"Future Simple замість Continuous для моменту","bad":"At 5 o'clock tomorrow I will work.","good":"At 5 o'clock tomorrow I <b>will be working</b>.","goodPlain":"At 5 o'clock tomorrow I will be working.","rule":"Певний момент у майбутньому: Future Continuous."},{"title":"Дієслово стану в Continuous","bad":"I will be knowing the results tomorrow.","good":"I <b>will know</b> the results tomorrow.","goodPlain":"I will know the results tomorrow.","rule":"Know, want, like — Future Simple."},{"title":"Порядок слів у питанні","bad":"Will be you using the car?","good":"<b>Will you be using</b> the car?","goodPlain":"Will you be using the car?","rule":"Will + підмет + be + V-ing."},{"title":"Will замість will be","bad":"What will you doing at 8?","good":"What <b>will you be doing</b> at 8?","goodPlain":"What will you be doing at 8?","rule":"Тут обов'язкове be."}]}$g78$::jsonb, null, 10, $g79$fut_cont$g79$
