insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g81$fp_form$g81$, $g82$Future Perfect: як утворюється$g82$, $g83$elementary$g83$, $g84$formula$g84$, $g85${"step":"Future Perfect: як утворюється","kicker":"Як утворюється","lead":"Future Perfect = <b>will have</b> + <b>третя форма</b> дієслова (V3). Правильні дієслова: V + ed; неправильні вчимо (<i>write – wrote – written</i>).","tiles":[{"role":"підмет","label":"I / he / they…","tone":"noun"},{"role":"will have","label":"will have","tone":"colour"},{"role":"V3","label":"finished / written","tone":"origin"}],"legend":[{"tone":"noun","label":"для всіх осіб — will have"},{"tone":"origin","label":"правильні: V + ed; неправильні: третя колонка"}],"examples":[{"text":"He <b>will have come</b> by 5 o'clock tomorrow evening.","plain":"He will have come by 5 o'clock tomorrow evening.","note":"ствердження"},{"text":"I <b>won't have finished</b> by Friday.","plain":"I won't have finished by Friday.","note":"заперечення"},{"text":"<b>Will</b> they <b>have arrived</b> by noon?","plain":"Will they have arrived by noon?","note":"питання"},{"text":"What book <b>will</b> he <b>have read</b> by next Tuesday?","plain":"What book will he have read by next Tuesday?","note":"спеціальне питання"}],"note":"Питальне слово + will + підмет + have + V3: <i>Who will have washed the dishes by 5 o'clock?</i> Скорочення: <i>I'll have finished, won't have finished</i>.","tabs":[{"title":"Усі форми","html":"<div class=\"overflow-x-auto mb-3\"><table class=\"w-full text-body-sm border-collapse\">\n  <thead><tr><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\"></th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Ствердження</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Заперечення</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Питання</th></tr></thead>\n  <tbody><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">I / you / he / she / it / we / they</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">will have finished</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">won't have finished</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">Will he have finished?</td></tr></tbody>\n</table></div>"}]}$g85$::jsonb, null, 11, $g86$fut_perf$g86$
