insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g88$fp_use$g88$, $g89$Future Perfect: коли вживаємо$g89$, $g90$elementary$g90$, $g91$cases$g91$, $g92${"kicker":"Коли вживаємо","lead":"Future Perfect дивиться з майбутнього назад: до цього моменту дія вже буде зроблена.","cards":[{"icon":"⏱","title":"Завершиться до певного моменту","text":"Названо крайній момент: by 6 o'clock, by Friday, by the end of the month.","example":"He <b>will have finished</b> his work by 6 o'clock.","examplePlain":"He will have finished his work by 6 o'clock."},{"icon":"⇤","title":"Завершиться до іншої дії в майбутньому","text":"By the time + Present Simple: дія в підрядному, Future Perfect — у головному.","example":"We <b>will have cleaned</b> the house by the time you arrive.","examplePlain":"We will have cleaned the house by the time you arrive."},{"icon":"✓","title":"Результат до потрібного часу","text":"Важливий результат, а не процес.","example":"The film <b>will have finished</b> by 7 o'clock.","examplePlain":"The film will have finished by 7 o'clock."}],"axis":{"title":"Future Perfect на осі","points":[{"label":"тепер","text":"говоримо"},{"label":"раніше за X","text":"will have + V3: дія завершилась"},{"label":"момент X","text":"by X"}],"note":"Після by the time, before, when, as soon as дієслово стоїть у Present Simple, а не в will."}}$g92$::jsonb, null, 12, $g93$fut_perf$g93$
