insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g95$fp_markers$g95$, $g96$Future Perfect: слова-маркери$g96$, $g97$elementary$g97$, $g98$pairs$g98$, $g99${"step":"Future Perfect: слова-маркери","kicker":"Слова-маркери","lead":"Маркери показують, до якого моменту дія завершиться.","groups":[{"title":"Крайній момент","note":"типові слова","items":[["by 7 o'clock","They will have decorated the square by 7 o'clock."],["by next Thursday","Jim will have written the report by next Thursday."],["by the end of the day","You will have typed five letters by the end of the day."],["by the time + Present Simple","I will have moved by the time you come."],["before + Present Simple","She will have gone before you arrive."]]}],"notes":["<b>Після by the time й before:</b> Present Simple. <i>By the time he comes, we will have left</i> — не <i>will come</i>."]}$g99$::jsonb, null, 13, $g100$fut_perf$g100$
