insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g102$fp_traps$g102$, $g103$Future Perfect: типові помилки$g103$, $g104$intermediate$g104$, $g105$traps$g105$, $g106${"kicker":"Типові помилки","lead":"Помилки бувають у структурі, у вживанні will після by the time та у виборі між Perfect і Continuous.","items":[{"title":"Забули have","bad":"She will finished the report by Friday.","good":"She <b>will have finished</b> the report by Friday.","goodPlain":"She will have finished the report by Friday.","rule":"will have + V3."},{"title":"Друга форма замість третьої","bad":"They will have went home by 5.","good":"They will have <b>gone</b> home by 5.","goodPlain":"They will have gone home by 5.","rule":"Після will have — V3: go – went – gone."},{"title":"Will у підрядному часу","bad":"We will have left by the time you will come.","good":"We will have left by the time you <b>come</b>.","goodPlain":"We will have left by the time you come.","rule":"Після by the time, before — Present Simple."},{"title":"Порядок слів у питанні","bad":"Will have Ron fixed this bike?","good":"<b>Will Ron have fixed</b> this bike?","goodPlain":"Will Ron have fixed this bike?","rule":"Will + підмет + have + V3."},{"title":"Future Continuous замість Perfect для результату","bad":"By Friday Susan will be passing all her exams.","good":"By Friday Susan <b>will have passed</b> all her exams.","goodPlain":"By Friday Susan will have passed all her exams.","rule":"By Friday — результат: Future Perfect."}]}$g106$::jsonb, null, 14, $g107$fut_perf$g107$
