insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g109$fpc_form$g109$, $g110$Future Perfect Continuous: як утворюється$g110$, $g111$elementary$g111$, $g112$formula$g112$, $g113${"step":"Future Perfect Continuous: як утворюється","kicker":"Як утворюється","lead":"Future Perfect Continuous = <b>will have been</b> + дієслово з <b>-ing</b>. Це найдовша форма: будь-який підмет, will have been, V-ing.","tiles":[{"role":"підмет","label":"I / he / they…","tone":"noun"},{"role":"will have been","label":"will have been","tone":"colour"},{"role":"V-ing","label":"working","tone":"origin"}],"legend":[{"tone":"noun","label":"для всіх осіб — will have been"},{"tone":"origin","label":"правопис -ing такий самий, як у Present Continuous"}],"examples":[{"text":"He <b>will have been working</b> here for a month by the 23rd of November.","plain":"He will have been working here for a month by the 23rd of November.","note":"ствердження"},{"text":"He <b>won't have been working</b> here for a month by then.","plain":"He won't have been working here for a month by then.","note":"заперечення"},{"text":"<b>Will</b> they <b>have been working</b> for two hours by the time the car arrives?","plain":"Will they have been working for two hours by the time the car arrives?","note":"питання"},{"text":"How long <b>will</b> you <b>have been waiting</b>?","plain":"How long will you have been waiting?","note":"спеціальне питання"}],"note":"Скорочення: <i>I'll have been working, won't have been working</i>. Коротка відповідь: <i>Yes, they will. / No, they won't.</i>","tabs":[{"title":"Усі форми","html":"<div class=\"overflow-x-auto mb-3\"><table class=\"w-full text-body-sm border-collapse\">\n  <thead><tr><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\"></th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Ствердження</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Заперечення</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Питання</th></tr></thead>\n  <tbody><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">I / you / he / she / it / we / they</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">will have been working</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">won't have been working</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">Will he have been working?</td></tr></tbody>\n</table></div>"}]}$g113$::jsonb, null, 15, $g114$fut_perf_cont$g114$
