insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g116$fpc_use$g116$, $g117$Future Perfect Continuous: коли вживаємо$g117$, $g118$elementary$g118$, $g119$cases$g119$, $g120${"kicker":"Коли вживаємо","lead":"Цей час відповідає на запитання «скільки це вже триватиме до певного моменту?». Він трапляється рідко, але з ним добре звучать рахунки й ювілеї.","cards":[{"icon":"⏳","title":"Тривалість до моменту в майбутньому","text":"Назване крайній момент і скільки дія вже триватиме.","example":"He <b>will have been working</b> as a surgeon for twenty-five years by the end of this year.","examplePlain":"He will have been working as a surgeon for twenty-five years by the end of this year."},{"icon":"📊","title":"Підкреслюємо процес, а не результат","text":"Нас цікавить, як довго, а не що вийшло.","example":"By 8 o'clock we <b>will have been surfing</b> the Net for five hours.","examplePlain":"By 8 o'clock we will have been surfing the Net for five hours."}]}$g120$::jsonb, null, 16, $g121$fut_perf_cont$g121$
