insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g123$fpc_markers$g123$, $g124$Future Perfect Continuous: слова-маркери$g124$, $g125$elementary$g125$, $g126$pairs$g126$, $g127${"step":"Future Perfect Continuous: слова-маркери","kicker":"Слова-маркери","lead":"Майже завжди є дві частини: <b>by</b> + момент і <b>for</b> + тривалість.","groups":[{"title":"Момент і тривалість","note":"часта пара","items":[["by + момент","by next month / by 8 o'clock / by the end of the year"],["for + тривалість","for five hours / for ten years / for two months"],["how long?","How long will you have been waiting by 6?"],["by the time + Present Simple","By the time he arrives, we will have been waiting for an hour."]]}],"notes":["<b>Дієслова стану</b> (know, like, want) — без Continuous: <i>By May I will have known him for ten years.</i>"]}$g127$::jsonb, null, 17, $g128$fut_perf_cont$g128$
