insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g130$fpc_vs_fp$g130$, $g131$Future Perfect чи Future Perfect Continuous?$g131$, $g132$elementary$g132$, $g133$pairs$g133$, $g134${"step":"Future Perfect чи Future Perfect Continuous?","kicker":"Порівняння","lead":"Обидва часи говорять про дію до моменту в майбутньому. Continuous дивиться на <b>процес і тривалість</b>, Perfect — на <b>результат і кількість</b>.","groups":[{"title":"Future Perfect Continuous: процес","note":"скільки триватиме","items":[["for + тривалість","She will have been writing for two hours by 5."],["How long?","How long will you have been waiting?"]]},{"title":"Future Perfect: результат","note":"скільки зроблено","items":[["How many? / how much?","She will have written five letters by 5."],["завершена дія","The film will have finished by 7."]]}],"notes":["<b>Порівняйте:</b> <i>By 5 she will have been writing letters for two hours</i> (процес) — <i>By 5 she will have written ten letters</i> (результат)."]}$g134$::jsonb, null, 18, $g135$fut_perf_cont$g135$
