insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g137$fpc_traps$g137$, $g138$Future Perfect Continuous: типові помилки$g138$, $g139$intermediate$g139$, $g140$traps$g140$, $g141${"kicker":"Типові помилки","lead":"Тут помиляються на структурі (will have been + -ing), на from / for та на вибір між Continuous і Perfect.","items":[{"title":"Забули been","bad":"By 5 o'clock she will have waiting for two hours.","good":"By 5 o'clock she <b>will have been waiting</b> for two hours.","goodPlain":"By 5 o'clock she will have been waiting for two hours.","rule":"will have been + V-ing."},{"title":"Future Continuous замість Perfect Continuous","bad":"By next Monday Bob will be working here for ten days.","good":"By next Monday Bob <b>will have been working</b> here for ten days.","goodPlain":"By next Monday Bob will have been working here for ten days.","rule":"For + by → Future Perfect Continuous."},{"title":"Порядок слів у питанні","bad":"Will been they working?","good":"<b>Will they have been</b> working?","goodPlain":"Will they have been working?","rule":"Will + підмет + have been + V-ing."},{"title":"Дієслово стану","bad":"I will have been knowing him for years.","good":"I <b>will have known</b> him for years.","goodPlain":"I will have known him for years.","rule":"Know — стан: Future Perfect."},{"title":"Will у підрядному часу","bad":"By the time he will arrive, we will have been waiting for an hour.","good":"By the time he <b>arrives</b>, we will have been waiting for an hour.","goodPlain":"By the time he arrives, we will have been waiting for an hour.","rule":"Після by the time — Present Simple."}]}$g141$::jsonb, null, 19, $g142$fut_perf_cont$g142$
