insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g144$fmix_choose$g144$, $g145$Як вибрати майбутній час$g145$, $g146$elementary$g146$, $g147$cases$g147$, $g148${"kicker":"Порівняння","lead":"Поставте собі запитання: <b>план чи миттєве рішення?</b> <b>момент чи завершення?</b> <b>результат чи тривалість?</b> Відповіді підкажуть форму.","cards":[{"icon":"1","title":"Will","text":"Прогноз, миттєве рішення, обіцянка, факт. Слова: I think, I hope, probably.","example":"I think it <b>will rain</b>. I'<b>ll help</b> you.","examplePlain":"I think it will rain. I'll help you."},{"icon":"2","title":"Be going to","text":"Намір, вже ухвалений план, очевидні ознаки.","example":"He <b>is going to buy</b> a new camera. Look: it <b>is going to rain</b>.","examplePlain":"He is going to buy a new camera. Look: it is going to rain."},{"icon":"3","title":"Present Continuous / Simple","text":"Домовленість (continuous) і розклад (simple).","example":"We <b>are flying</b> tomorrow. The plane <b>leaves</b> at 9.","examplePlain":"We are flying tomorrow. The plane leaves at 9."},{"icon":"4","title":"Future Continuous","text":"Дія в процесі в певний момент майбутнього; ввічливе запитання.","example":"At 5 I <b>will be working</b>. <b>Will you be using</b> the car?","examplePlain":"At 5 I will be working. Will you be using the car?"},{"icon":"5","title":"Future Perfect","text":"Завершиться до моменту. Слова: by, by the time.","example":"I <b>will have finished</b> by 6.","examplePlain":"I will have finished by 6."},{"icon":"6","title":"Future Perfect Continuous","text":"Тривалість до моменту. Слова: for + by.","example":"By June I <b>will have been working</b> here for ten years.","examplePlain":"By June I will have been working here for ten years."}],"axis":{"title":"Те саме в майбутніх часах","points":[{"label":"Simple","text":"He will read a book (прогноз)"},{"label":"Continuous","text":"He will be reading at 8 (процес)"},{"label":"Perfect","text":"He will have read it by 8 (завершить)"},{"label":"Perfect Cont.","text":"He will have been reading for an hour by 8 (тривалість)"}]}}$g148$::jsonb, null, 20, $g149$fut_mix$g149$
